"use client";

import { useAppContext } from "@providers/AppContext";
import { useRef, useState, useEffect } from "react";
import { useTheme } from "@providers/ThemeProvider";
import Image from "next/image";
import MainMenu from "@components/layout/main-menu";
import { User, useAuth } from "@providers/AuthProvider";


export default function SideBarSmall() {

  // Getting the theme
  const { theme } = useTheme();
  const darkTheme = theme === "dark";

  // Getting the app context for layout functions on sidebar
  const { toggleSearch, mainMenuVisible, sidebarExpanded, toggleMainMenu, setMainMenuVisible, toggleSidebar } =
    useAppContext();

  // Setting references for menu and menu btn which is user profile icon
  const mainMenuRef = useRef<HTMLDivElement | null>(null);
  const mainMenuToggleBtnRef = useRef<HTMLDivElement | null>(null);
  const sidebarRef = useRef<HTMLDivElement | null>(null);

  // Setting fake user for testing and dev
  const [userInfo, setUserInfo] = useState<User | null>(null);
  if (!userInfo) {
    setUserInfo({
      userID: "",
      profilePicture: "/images/profile.png",
      email: "Not Signed In",
      username: "guestuser",
      firstName: "Not",
      lastName: "Signed In",
    });
  }

    // Sidebar empty-area click (ONLY when collapsed)
    const handleSidebarClick = (e: React.MouseEvent) => {
      if (!sidebarExpanded) {
        const target = e.target as HTMLElement;
  
        // Ignore clicks on buttons, icons, links
        if (target.closest("button, i, a")) return;
  
        toggleSidebar();
      }
    }

  // Closing the menu if clicked outside
  useEffect(() => {
    const closeIfOutside = (e: MouseEvent) => {
      if (
        mainMenuVisible &&
        mainMenuRef.current &&
        !mainMenuRef.current.contains(e.target as Node) &&
        !mainMenuToggleBtnRef.current?.contains(e.target as Node)
      ) {
        setMainMenuVisible(false);
      }
    };
    window.addEventListener("click", closeIfOutside);
    return () => window.removeEventListener("click", closeIfOutside);
  }, [mainMenuVisible]);

  // Sidebar items for getting mapped to the sidebar
  const sidebarItems = [
    {
      icon: (
        <i
          className="bx bx-edit text-text"
          style={{ fontSize: "24px" }}
        />
      ),
      onClick: null,
    },
    {
      icon: (
        <i
          className="bx bx-search text-text"
          style={{ fontSize: "24px" }}
        />
      ),
      onClick: toggleSearch,
    },
  ];

  // Returning the sidebar UI
  return (
    <div
      className={`relative w-[60px] h-full z-100 my-6 bg-bg-tertiary`}
      onClick={handleSidebarClick}
      ref={sidebarRef}
    >

      {/* Sidebar layout: header + main section */}
      <div className="w-[60px] h-full flex flex-col">

        {/* Logo Section */}
        <div className="p-4">
          <Image
            src={`/logos/${darkTheme ? "white_triangle" : "black_triangle"}.png`}
            alt="Woah AI"
            width={24}
            height={24}
          />
        </div>

        {/* Main content: top menu + bottom profile */}
        <div className="flex flex-col justify-between flex-1 px-4 pt-4">

          {/* Top menu */}
          <div className="flex flex-col gap-4">
            {sidebarItems.map((item, idx) => (
              <div
                key={idx}
                className="flex items-center gap-3 cursor-pointer text-text"
                onClick={item.onClick || undefined}
              >
                {item.icon}
              </div>
            ))}
          </div>

          {/* Bottom profile / account button */}
          <div
            className="flex flex-col items-center gap-3 cursor-pointer text-text"
          >
            <div
              ref={mainMenuToggleBtnRef}
              onClick={toggleMainMenu}
              className="flex items-center gap-3 cursor-pointer text-text"
            >
              {userInfo?.profilePicture && userInfo?.profilePicture?.length > 0 ? (
                <Image src={userInfo?.profilePicture} alt="Profile Picture" width={32} height={32} className="rounded-full" />
              ) : (
                <i
                  className="bx bx-user text-text"
                  style={{ fontSize: "32px" }}
                />)}
            </div>
          </div>
        </div>
      </div>

      {/* MoreBar popup */}
      {mainMenuVisible && (
        <div
          className="absolute"
          ref={mainMenuRef}
        >
          <MainMenu onClickToggle={() => setMainMenuVisible(false)} position={{ zIndex: 100, width: "215px", height: "290px", top: "auto", left: `10px`, right: "auto", bottom: "50px" }} />
        </div>
      )}
    </div>
  );
}
